<script setup lang="ts">import{computed,nextTick,ref,watch}from"vue";import type{IptvChannelRecord,IptvSourceRecord}from"@/types/records";import{rankPlaybackSources}from"@/domain/iptv/sourceSelection";const props=defineProps<{channel:IptvChannelRecord|null;links:IptvSourceRecord[];open:boolean}>();const emit=defineEmits<{close:[]}>();const selectedUrl=ref(""),failedUrls=ref<string[]>([]),message=ref(""),media=ref<HTMLMediaElement|null>(null);const sources=computed(()=>props.channel?rankPlaybackSources(props.channel,props.links):[]);const source=computed(()=>sources.value.find(x=>x.url===selectedUrl.value)||sources.value[0]);const playable=computed(()=>source.value&&!source.value.requiresBackend&&["http","audio","hls"].includes(source.value.type));const isAudio=computed(()=>source.value?.type==="audio");watch(()=>props.open,async open=>{if(!open)return;failedUrls.value=[];message.value="";selectedUrl.value=sources.value[0]?.url||"";await nextTick();media.value?.play().catch(()=>undefined)});function nextSource(){if(source.value)failedUrls.value.push(source.value.url);const next=sources.value.find(x=>!failedUrls.value.includes(x.url)&&!x.requiresBackend);if(next){selectedUrl.value=next.url;message.value=`A tentar fonte alternativa: ${next.label}.`}else message.value="Todas as fontes reproduzíveis falharam."}function onError(){nextSource()}</script><template><Teleport to="body"><div v-if="open&&channel" class="dialog-backdrop" @click.self="emit('close')"><section class="dialog-panel stream-player" role="dialog" aria-modal="true" aria-labelledby="stream-player-title" @keydown.esc="emit('close')"><div class="dialog-header"><div><p class="eyebrow">Reprodução em direto</p><h2 id="stream-player-title">{{channel.nome}}</h2></div><button class="icon-button" type="button" aria-label="Fechar player" @click="emit('close')">×</button></div><label v-if="sources.length>1" class="form-field"><span>Fonte</span><select v-model="selectedUrl"><option v-for="item in sources" :key="item.url" :value="item.url" :disabled="item.requiresBackend">{{item.label}} · {{item.type.toUpperCase()}} · {{item.state}}</option></select></label><p v-if="message" class="form-alert" aria-live="polite">{{message}}</p><p v-if="source?.requiresBackend" class="form-alert form-alert-error" role="alert">Esta fonte requer cabeçalhos especiais ou um protocolo suportado pelo backend local.</p><p v-else-if="!playable" class="form-alert" role="status">Não existe uma fonte reproduzível diretamente no navegador.</p><audio v-else-if="isAudio" ref="media" class="stream-media" controls autoplay :src="source?.url" @error="onError"/><video v-else ref="media" class="stream-media" controls autoplay playsinline :src="source?.url" @error="onError">O navegador não suporta vídeo HTML5.</video><p v-if="source?.type==='hls'" class="field-hint">O navegador tentará HLS nativo. Em navegadores sem HLS nativo, seleciona outra fonte ou usa o backend local.</p><div class="form-actions"><button class="button button-secondary" type="button" :disabled="!playable" @click="nextSource">Tentar fonte seguinte</button><button class="button button-secondary" type="button" @click="emit('close')">Fechar</button></div></section></div></Teleport></template>
